          TreeViewStories.WithControlledExpansion,
          "import { Document, Folder } from '@carbon/icons-react';"
        ),
    },
  ]}
/>

## With Icons

The `renderIcon` prop can be used to customize the icons of each node in the
TreeView.

<Canvas
  of={TreeViewStories.WithIcons}
